$db='MELISA_ERP_CRM_SHARED_TEST_20261009_02';$server='Semih\MELISADEV';$ready='dbo.usp_stage4_copy_ready';$immutable='dbo.immutable_stage4_copy_ready_revisions';$rehearsalPath=Join-Path $root 'business-ready-revision-rehearsal.json'
if($a.schemaVersion-cne 'melisa-business-copy-ready-install.v1'-or$a.target.database-cne $db-or$a.target.server-cne $server-or$a.target.login-cne 'melisa_shared_test_rw_20261009_02'-or$a.copyId-cne $b.copyId-or$a.copyId-cne $c.copyContext.copyId-or$a.baseSealHash-cne $c.copyContext.sealHash-or$a.baseSealHash-cne $b.config.copyContext.sealHash-or$a.backupSHA-cne $c.copyContext.backupSHA-or$a.revision.version-ne 1-or$a.replacements.Count-ne 1-or$a.revision.modules.Count-ne 1-or$b.moduleManifest.Count-ne 185-or$b.sourceModuleHashes.Count-ne 337-or$b.sourceChecks.Count-ne 227-or$c.database-cne $db-or$c.server-cne $server-or$c.businessReadyRevision-or$c.copyAdapterRevision){throw 'BUSINESS_READY_TARGET'}
$m=$a.replacements[0];$pin=@($b.moduleManifest|Where-Object name -CEQ $ready)
