if($Mode-ceq 'Apply'){$r=Get-Content -LiteralPath $rehearsalPath -Raw|ConvertFrom-Json;if($r.status-cne 'PASS'-or$r.rolledBack-ne $true-or$r.artifactSHA256-ine $RevisionSHA256-or$r.revisionHash-cne $a.revision.revisionHash-or$r.businessBefore-cne $r.businessAfter){throw 'BUSINESS_READY_REHEARSAL_REQUIRED'}}
$raw=Get-Content -LiteralPath (Join-Path $root 'shared-raw-copy.json') -Raw|ConvertFrom-Json -AsHashtable -Depth 100;if($raw.identity.database-cne $db-or$raw.identity.server-cne $server-or$raw.groups.Count-ne 51){throw 'BUSINESS_READY_SOURCE_PROOF'}
$cn=[Data.SqlClient.SqlConnection]::new("Server=$server;Database=$db;Integrated Security=True;Encrypt=False;Application Name=BUSINESS-READY-REVISION-OWNER");$tx=$null;$phase='CONNECT';$committed=$false
function Execute([string]$text){$cmd=$cn.CreateCommand();$cmd.Transaction=$tx;$cmd.CommandTimeout=900;$cmd.CommandText=$text;try{[void]$cmd.ExecuteNonQuery()}finally{$cmd.Dispose()}}
function Scalar([string]$text){$cmd=$cn.CreateCommand();$cmd.Transaction=$tx;$cmd.CommandTimeout=900;$cmd.CommandText=$text;try{return $cmd.ExecuteScalar()}finally{$cmd.Dispose()}}
function BusinessSnapshot{
 $groups=[ordered]@{};foreach($name in @($raw.groups.Keys|Sort-Object)){if($name-cnotmatch '^(dbo|erp_migration)\.[a-zA-Z0-9_]+$'){throw 'BUSINESS_READY_SNAPSHOT_TABLE'};$parts=$name.Split('.');$qualified='['+$parts[0]+'].['+$parts[1]+']';$cmd=$cn.CreateCommand();$cmd.Transaction=$tx;$cmd.CommandTimeout=900;$cmd.CommandText="SELECT CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT x.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)),2) rowHash FROM $qualified x ORDER BY rowHash";$r=$cmd.ExecuteReader();$digest=[Security.Cryptography.IncrementalHash]::CreateHash([Security.Cryptography.HashAlgorithmName]::SHA256);$count=0L;try{$digest.AppendData([Text.Encoding]::UTF8.GetBytes('['));while($r.Read()){$h=$r.GetString(0);if($h-cnotmatch '^[A-F0-9]{64}$'){throw 'BUSINESS_READY_ROW_HASH'};$prefix=if($count-eq 0){'"'}else{',"'};$digest.AppendData([Text.Encoding]::UTF8.GetBytes($prefix+$h+'"'));$count++};$digest.AppendData([Text.Encoding]::UTF8.GetBytes(']'));$groups[$name]=[ordered]@{count=$count;hash=[Convert]::ToHexString($digest.GetHashAndReset())}}finally{$r.Close();$cmd.Dispose();$digest.Dispose()}};return $groups
}
function Hash($value){$sha=[Security.Cryptography.SHA256]::Create();try{return [Convert]::ToHexString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes(($value|ConvertTo-Json -Depth 10 -Compress))))}finally{$sha.Dispose()}}
function ProtectedSQLSnapshot{
 $modules=Scalar "SELECT CONCAT(COUNT_BIG(*),N'|',CONVERT(varchar(64),HASHBYTES('SHA2_256',STRING_AGG(CONVERT(nvarchar(max),CONCAT(OBJECT_SCHEMA_NAME(m.object_id),N'.',OBJECT_NAME(m.object_id),N'|',CONVERT(varchar(64),HASHBYTES('SHA2_256',m.definition),2))),N';') WITHIN GROUP(ORDER BY m.object_id)),2)) FROM sys.sql_modules m WHERE m.object_id NOT IN(OBJECT_ID(N'$ready'),ISNULL(OBJECT_ID(N'$immutable'),0))"
 $checks=Scalar "SELECT CONCAT(COUNT_BIG(*),N'|',CONVERT(varchar(64),HASHBYTES('SHA2_256',STRING_AGG(CONVERT(nvarchar(max),CONCAT(object_id,N'|',parent_object_id,N'|',name,N'|',definition,N'|',is_disabled,N'|',is_not_trusted,N'|',is_not_for_replication,N'|',parent_column_id)),N';') WITHIN GROUP(ORDER BY object_id)),2)) FROM sys.check_constraints WHERE parent_object_id<>ISNULL(OBJECT_ID(N'dbo.stage4_copy_ready_revisions'),0)"
 $triggers=Scalar "SELECT CONVERT(varchar(64),HASHBYTES('SHA2_256',STRING_AGG(CONVERT(nvarchar(max),CONCAT(t.object_id,N'|',t.name,N'|',t.is_disabled,N'|',OBJECTPROPERTY(t.object_id,'ExecIsFirstInsertTrigger'),N'|',OBJECTPROPERTY(t.object_id,'ExecIsFirstUpdateTrigger'),N'|',OBJECTPROPERTY(t.object_id,'ExecIsFirstDeleteTrigger'),N'|',CONVERT(varchar(64),HASHBYTES('SHA2_256',OBJECT_DEFINITION(t.object_id)),2))),N';') WITHIN GROUP(ORDER BY t.object_id)),2) FROM sys.triggers t WHERE t.name<>N'immutable_stage4_copy_ready_revisions'"
 return @{modules=$modules;checks=$checks;triggers=$triggers}
}
try{
 $cn.Open();if((Scalar "SELECT CONCAT(CONVERT(nvarchar(128),SERVERPROPERTY('ServerName')),N'|',DB_NAME(),N'|',IS_SRVROLEMEMBER('sysadmin'))")-cne "$server|$db|1"){throw 'BUSINESS_READY_OWNER_IDENTITY'}
 $tx=$cn.BeginTransaction([Data.IsolationLevel]::Serializable);$phase='VERIFY_BASE'
 if((Scalar "SELECT COUNT(*) FROM dbo.stage4_copy_manifest WHERE copy_id='$($a.copyId)' AND seal_hash='$($a.baseSealHash)' AND backup_sha='$($a.backupSHA)' AND sealed=1")-ne 1-or(Scalar 'SELECT COUNT(*) FROM dbo.stage4_copy_manifest')-ne 1-or(Scalar 'SELECT COUNT(*) FROM dbo.stage4_copy_module_manifest')-ne 185-or(Scalar "SELECT COUNT(*) FROM sys.tables WHERE object_id=OBJECT_ID(N'dbo.stage4_copy_ready_revisions')")-ne 0-or(Scalar "SELECT COUNT(*) FROM dbo.stage4_copy_module_manifest WHERE after_hash<>CONVERT(varchar(64),HASHBYTES('SHA2_256',OBJECT_DEFINITION(OBJECT_ID(name))),2)")-ne 0){throw 'BUSINESS_READY_BASE_DRIFT'}
 foreach($entry in $b.moduleManifest){if($entry.name-cnotmatch '^dbo\.[a-zA-Z0-9_]+$'-or$entry.afterHash-cnotmatch '^[A-F0-9]{64}$'-or(Scalar "SELECT COUNT(*) FROM dbo.stage4_copy_module_manifest WHERE name=N'$($entry.name)' AND after_hash=N'$($entry.afterHash)' AND ISNULL(before_hash,N'')=N'$($entry.beforeHash)' AND kind=N'$($entry.kind)'")-ne 1){throw 'BUSINESS_READY_BASE_MANIFEST_DRIFT'}}
 if((Scalar "SELECT CONVERT(varchar(64),HASHBYTES('SHA2_256',OBJECT_DEFINITION(OBJECT_ID(N'$ready'))),2)")-cne $m.beforeHash){throw 'BUSINESS_READY_BEFORE_HASH'}
 $phase='SNAPSHOT_BEFORE';Write-Output '{"phase":"BUSINESS_READY_SNAPSHOT_BEFORE"}';$before=BusinessSnapshot;$beforeHash=Hash $before;$sqlBefore=ProtectedSQLSnapshot
 $phase='CREATE_APPEND_ONLY_REGISTRY';Execute $a.tableSQL;Execute $a.immutableSQL
 if((Scalar "SELECT CONVERT(varchar(64),HASHBYTES('SHA2_256',OBJECT_DEFINITION(OBJECT_ID(N'$immutable'))),2)")-cne $a.revision.immutableTriggerHash){throw 'BUSINESS_READY_IMMUTABLE_HASH'}
 $phase='REPLACE_READY_ONLY';Execute $m.definition;if((Scalar "SELECT CONVERT(varchar(64),HASHBYTES('SHA2_256',OBJECT_DEFINITION(OBJECT_ID(N'$ready'))),2)")-cne $m.afterHash){throw 'BUSINESS_READY_AFTER_HASH'}
 $phase='APPEND_REVISION';Execute "INSERT dbo.stage4_copy_ready_revisions(copy_id,revision,base_seal_hash,name,before_hash,after_hash,revision_hash)VALUES('$($a.copyId)',1,'$($a.baseSealHash)',N'$ready','$($m.beforeHash)','$($m.afterHash)','$($a.revision.revisionHash)')"
 if((Scalar 'SELECT COUNT(*) FROM dbo.stage4_copy_ready_revisions')-ne 1-or(Scalar 'SELECT COUNT(*) FROM sys.triggers WHERE is_disabled=1')-ne 0){throw 'BUSINESS_READY_REGISTRY_DRIFT'}
 $phase='GRANT_METADATA_ONLY';foreach($principal in @('melisa_shared_test_ro_20261009_02','melisa_shared_test_rw_20261009_02')){Execute "GRANT SELECT ON OBJECT::dbo.stage4_copy_ready_revisions TO [$principal];GRANT VIEW DEFINITION ON OBJECT::dbo.stage4_copy_ready_revisions TO [$principal];GRANT VIEW DEFINITION ON OBJECT::$ready TO [$principal];"}
 $phase='VERIFY_UNCHANGED_SQL';$sqlAfter=ProtectedSQLSnapshot;foreach($key in $sqlBefore.Keys){if($sqlBefore[$key]-cne $sqlAfter[$key]){throw 'BUSINESS_READY_EXISTING_SQL_OR_CHECK_DRIFT'}}
 $phase='SNAPSHOT_AFTER';Write-Output '{"phase":"BUSINESS_READY_SNAPSHOT_AFTER"}';$after=BusinessSnapshot;$afterHash=Hash $after;if($beforeHash-cne $afterHash){throw 'BUSINESS_READY_BUSINESS_DRIFT'}
 $proof=[ordered]@{status='PASS';database=$db;copyId=$a.copyId;revisionHash=$a.revision.revisionHash;artifactSHA256=$RevisionSHA256.ToUpperInvariant();businessTables=51;businessBefore=$beforeHash;businessAfter=$afterHash;businessWrites=0;baseManifestRows=185;profileUnchanged=$true;sourceModulePins=337;sourceCheckPins=227;existingSQLBefore=$sqlBefore;existingSQLAfter=$sqlAfter;guardsDisabled=0;existingRolesChanged=$false;recordedAt=[DateTime]::UtcNow.ToString('o')}
 if($Mode-ceq 'Rehearse'){$tx.Rollback();$tx.Dispose();$tx=$null;$proof.rolledBack=$true;[IO.File]::WriteAllText($rehearsalPath,($proof|ConvertTo-Json -Depth 10),[Text.UTF8Encoding]::new($false));$proof|ConvertTo-Json -Depth 4;return}
 $phase='COMMIT';$tx.Commit();$tx.Dispose();$tx=$null;$committed=$true;$proof.sqlCommitted=$true;$proof.configAdjunctPersisted=$false;$proofPath=Join-Path $root 'business-ready-revision-applied.json';[IO.File]::WriteAllText($proofPath,($proof|ConvertTo-Json -Depth 10),[Text.UTF8Encoding]::new($false))
